<?phpnamespace app\api\controller\market;use app\api\controller\Controller;use app\api\model\SignLog as SignLogModel;use app\api\model\Setting as SettingModel;use think\facade\Cache;/** * 签到管理 */class Sign extends Controller{    /**     * 是否签到     */    public function isSign()    {        $model = new SignLogModel;        $isSign = $model->getIsSign($this->user_id);//获取今天是否签到过        $setting = SettingModel::getItem('sign');//签到配置参数        $sign_in=0;//连续签到天数        //如果有签到套餐        if(sizeof($setting['plan']) > 0){            $setting['plan'] = array_sort($setting['plan'], 'days');//按照天数从小到大排序            $sign_in = Cache::get('sign_' . $this->user_id,0);//获取连续签到天数            foreach($setting['plan'] as $item){                if($sign_in < $item['days']){                    $plan = [];//签到任务进度数据                    for($n=0;$n<$item['days'];$n++){                        $plan[] = $n+1;                    }                    $setting['plan'] = $plan;                    if($item['type'] == 'score'){                        $title = '个积分';                    }else{                        $title = '元余额';                    }                    $setting['plan_title'] = '连续签到' . $item['days'] . '天，赠送' . $item['number'] . $title;                    break;                }            }        }        return $this->renderSuccess(compact('isSign','setting','sign_in'));    }    /**     * 签到     */    public function sign()    {        $model = new SignLogModel;        if($model->add($this->user_id)){            return $this->renderMsg('签到成功');        }        $error = $model->getError() ?: '签到失败';		return $this->renderError($error);    }    /**     * 签到记录     */    public function logs()    {        $model = new SignLogModel;        $list = $model->getList($this->user_id);        return $this->renderSuccess($list);    }}